"kind": "propose",
"summary": "The current revision's memory limit is too low, leading to OOM kills. Increasing the memory limit to 1.25Gi should resolve this.",
"hypotheses": [
    {
        "root_cause_class": "memory_limit_too_low",
        "summary": "The app's memory usage peaked at 100% of its 1Gi limit, causing OOM kills. The previous revision ran without issues with the same limit, indicating the limit is insufficient for the current workload.",
        "supporting": ["oom_killed_current_revision", "memory_at_limit_before_kill", "memory_data_available"],
        "contradicting": ["earlier_revision_healthy"],
        "missing": ["container_memory.peakBytes", "container_memory.usageBytes"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "The evidence does not conclusively show whether the memory limit is the root cause or if other factors like memory leaks are involved.",
        "supporting": ["oom_after_long_run"],
        "contradicting": ["memory_at_limit_before_kill"],
        "missing": ["container_logs_tail"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-resources",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "sessions",
        "uid": "uid-deployment-sessions"
    },
    "params": {
        "containers": {
            "app": {
                "limits": {
                    "memory": "1250Mi"
                }
            }
        }
    },
    "expected_effect": "The increased memory limit should prevent OOM kills by allowing the app to use more memory before being terminated.",
    "rationale": "The app's memory usage peaked at 100% of its 1Gi limit, causing OOM kills. The previous revision ran without issues with the same limit, indicating the limit is insufficient for the current workload. Increasing the limit by 25% (to 1.25Gi) should provide enough memory to prevent OOM kills without requiring further changes to the app or node resources.",
    "cited_evidence_ids": ["ev-container_memory", "ev-rollout_history", "ev-revision_health"],
    "cited_predicates": ["oom_killed_current_revision", "memory_at_limit_before_kill", "memory_data_available"]
}
}
